cypress_script:
describe('TodoMVC CRUD Operations', () => {
  it('should add a new todo', () => {
    cy.visit('https://todomvc.com/examples/react/dist/');
    cy.get('[data-testid=text-input]').type('New Todo{enter}');
    cy.get('[data-testid=todo-list]').children().should('have.length', 1);
  });
  it('should not add an empty todo', () => {
    cy.visit('https://todomvc.com/examples/react/dist/');
    cy.get('[data-testid=text-input]').type('{enter}');
    cy.url().should('eq', 'https://todomvc.com/examples/react/dist/');
    cy.get('[data-testid=todo-list]').children().should('have.length', 0);
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('TodoMVC CRUD Operations', () => {
  test('should add a new todo', async ({ page }) => {
    await page.goto('https://todomvc.com/examples/react/dist/');
    await page.fill('[data-testid=text-input]', 'New Todo');
    await page.press('[data-testid=text-input]', 'Enter');
    const todos = await page.locator('[data-testid=todo-list]').locator('li');
    expect(await todos.count()).toBe(1);
  });
  test('should not add an empty todo', async ({ page }) => {
    await page.goto('https://todomvc.com/examples/react/dist/');
    await page.press('[data-testid=text-input]', 'Enter');
    expect(page.url()).toBe('https://todomvc.com/examples/react/dist/');
    const todos = await page.locator('[data-testid=todo-list]').locator('li');
    expect(await todos.count()).toBe(0);
  });
});
